import javax.swing.*;import java.awt.*;import java.sql.*;
public class TransferFrame extends JFrame{JTextField f=new JTextField(),t=new JTextField(),a=new JTextField(),d=new JTextField();public TransferFrame(){setTitle("Transfer Money");setSize(620,500);setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel p=new JPanel(null);p.setBackground(new Color(230,240,255));JLabel h=new JLabel("TRANSFER MONEY",SwingConstants.CENTER);h.setFont(new Font("Arial",1,22));h.setBounds(150,25,320,35);p.add(h);lab(p,"From Account ID:",70,90);fld(p,f,220,90);lab(p,"To Account ID:",70,140);fld(p,t,220,140);lab(p,"Amount:",70,190);fld(p,a,220,190);lab(p,"Description:",70,240);fld(p,d,220,240);JButton b=new JButton("TRANSFER");b.setBounds(120,330,150,40);p.add(b);b.addActionListener(e->go());add(p);}void lab(JPanel p,String s,int x,int y){JLabel l=new JLabel(s);l.setBounds(x,y,140,30);p.add(l);}void fld(JPanel p,JTextField x,int a,int b){x.setBounds(a,b,280,30);p.add(x);}void go(){try{int from=Integer.parseInt(f.getText().trim()),to=Integer.parseInt(t.getText().trim());double am=Double.parseDouble(a.getText().trim());if(from==to||am<=0){JOptionPane.showMessageDialog(this,"Invalid accounts or amount!");return;}Connection c=DBConnection.getConnection();try{c.setAutoCommit(false);double bal;try(PreparedStatement q=c.prepareStatement("SELECT BALANCE FROM BANK_ACCOUNTS WHERE ACCOUNT_ID=? AND STATUS='ACTIVE' FOR UPDATE")){q.setInt(1,from);try(ResultSet r=q.executeQuery()){if(!r.next()){JOptionPane.showMessageDialog(this,"From account not found/inactive!");c.rollback();return;}bal=r.getDouble(1);}}try(PreparedStatement q=c.prepareStatement("SELECT ACCOUNT_ID FROM BANK_ACCOUNTS WHERE ACCOUNT_ID=? AND STATUS='ACTIVE' FOR UPDATE")){q.setInt(1,to);try(ResultSet r=q.executeQuery()){if(!r.next()){JOptionPane.showMessageDialog(this,"To account not found/inactive!");c.rollback();return;}}}if(bal<am){JOptionPane.showMessageDialog(this,"Insufficient balance!");c.rollback();return;}try(PreparedStatement q=c.prepareStatement("UPDATE BANK_ACCOUNTS SET BALANCE=BALANCE-? WHERE ACCOUNT_ID=?")){q.setDouble(1,am);q.setInt(2,from);q.executeUpdate();}try(PreparedStatement q=c.prepareStatement("UPDATE BANK_ACCOUNTS SET BALANCE=BALANCE+? WHERE ACCOUNT_ID=?")){q.setDouble(1,am);q.setInt(2,to);q.executeUpdate();}try(PreparedStatement q=c.prepareStatement("INSERT INTO BANK_TRANSFERS VALUES(BANK_TRANSFER_SEQ.NEXTVAL,?,?,?,SYSDATE,?)")){q.setInt(1,from);q.setInt(2,to);q.setDouble(3,am);q.setString(4,d.getText().trim());q.executeUpdate();}c.commit();JOptionPane.showMessageDialog(this,"Transfer Successful!");}catch(SQLException e){c.rollback();throw e;}finally{c.close();}}catch(NumberFormatException e){JOptionPane.showMessageDialog(this,"Account IDs and amount must be valid!");}catch(SQLException e){JOptionPane.showMessageDialog(this,"Database Error: "+e.getMessage());}}}
